-- pg_trgm powers the partial-match plate and chassis search below (trigram GIN indexes).
-- Edited by hand: the extension line and the trigger at the end aren't generated by drizzle-kit.
CREATE EXTENSION IF NOT EXISTS pg_trgm;--> statement-breakpoint
CREATE TABLE "car_aliases" (
	"alias_id" uuid PRIMARY KEY NOT NULL,
	"car_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "car_aliases_not_self" CHECK ("car_aliases"."alias_id" <> "car_aliases"."car_id")
);
--> statement-breakpoint
CREATE TABLE "cars" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"reg_no" varchar(15),
	"reg_year" smallint,
	"chassis_no" varchar(30),
	"make" text,
	"model" text,
	"year" smallint,
	"merged_into_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "cars_reg_no_unique" UNIQUE("reg_no"),
	CONSTRAINT "cars_chassis_no_unique" UNIQUE("chassis_no"),
	CONSTRAINT "cars_has_identifier" CHECK ("cars"."reg_no" IS NOT NULL OR "cars"."chassis_no" IS NOT NULL),
	CONSTRAINT "cars_reg_no_normalised" CHECK ("cars"."reg_no" ~ '^[A-Z0-9]{3,15}$' AND "cars"."reg_no" ~ '[A-Z]' AND "cars"."reg_no" ~ '[0-9]'),
	CONSTRAINT "cars_chassis_no_normalised" CHECK ("cars"."chassis_no" ~ '^[A-Z0-9]{6,30}$'),
	CONSTRAINT "cars_year_range" CHECK ("cars"."year" BETWEEN 1950 AND 2100),
	CONSTRAINT "cars_reg_year_range" CHECK ("cars"."reg_year" BETWEEN 1950 AND 2100),
	CONSTRAINT "cars_not_merged_into_self" CHECK ("cars"."merged_into_id" <> "cars"."id")
);
--> statement-breakpoint
ALTER TABLE "car_aliases" ADD CONSTRAINT "car_aliases_car_id_cars_id_fk" FOREIGN KEY ("car_id") REFERENCES "public"."cars"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "cars" ADD CONSTRAINT "cars_merged_into_id_cars_id_fk" FOREIGN KEY ("merged_into_id") REFERENCES "public"."cars"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "car_aliases_car_id_index" ON "car_aliases" USING btree ("car_id");--> statement-breakpoint
CREATE INDEX "cars_reg_no_trgm" ON "cars" USING gin ("reg_no" gin_trgm_ops);--> statement-breakpoint
CREATE INDEX "cars_chassis_no_trgm" ON "cars" USING gin ("chassis_no" gin_trgm_ops);--> statement-breakpoint
CREATE INDEX "cars_merged_into_id_index" ON "cars" USING btree ("merged_into_id");
